import java.util.Scanner;

public class PiglatinWordConverter {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a word in uppercase: ");
        String str = sc.next().toUpperCase();

        int vIdx = -1;
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if ("AEIOU".indexOf(ch) != -1) {
                vIdx = i;
                break;
            }
        }

        if (vIdx != -1) {
            String piglatin = str.substring(vIdx) + str.substring(0, vIdx) + "AY";
            System.out.println("Original Word: " + str);
            System.out.println("Piglatin Form: " + piglatin);
        } else {
            System.out.println("No vowels found in " + str + " - cannot convert to Piglatin.");
        }
    }
}
/*
VARIABLE DESCRIPTION TABLE:
Variable Name | Data Type | Purpose
str           | String    | Stores input word in uppercase
vIdx          | int       | Index of first occurrence of a vowel (-1 if none)
i             | int       | Traversal loop counter
ch            | char      | Extracted character at index i
piglatin      | String    | Converted Piglatin word
*/
