import java.util.Scanner;

public class SentencePiglatin {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        String s = sc.nextLine().toUpperCase().trim() + " ";

        String word = "";
        String result = "";

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch != ' ') {
                word = word + ch;
            } else {
                int vIdx = -1;
                for (int j = 0; j < word.length(); j++) {
                    if ("AEIOU".indexOf(word.charAt(j)) != -1) {
                        vIdx = j;
                        break;
                    }
                }
                if (vIdx != -1) {
                    result = result + word.substring(vIdx) + word.substring(0, vIdx) + "AY ";
                } else {
                    result = result + word + "AY ";
                }
                word = "";
            }
        }
        System.out.println("Piglatin Sentence: " + result.trim());
    }
}
